#!/bin/bash
period=20
dumpNr=0
sysStats=("uptime" "stat" "meminfo" "interrupts" "msg_rtr_arm")
fzcsysStats=("uptime" "stat" "meminfo" "interrupts" "pss")
logsDir="/nfs/benchmark/logs"
clear_flag=0
declare -A ccsStats=()
verbose=0
is_fzc=0

declare -A commands=(
    ["systime"]="date +%s"
    ["diskspace"]="df"
    ["qlen"]="qlen"
    ["loadavg"]="cat /proc/loadavg"
    ["hwqueues"]="cat /sys/kernel/debug/qmss"
    #["temperature"]="echo -n 'K2ext: ';cat /sys/bus/i2c/devices/2-004c/temp1_input;cat /sys/bus/i2c/devices/2-004c/hwmon/hwmon[0-9]*/temp1_input;echo -n 'K2int: ';cat /sys/bus/i2c/devices/2-004c/temp2_input;cat /sys/bus/i2c/devices/2-004c/hwmon/hwmon[0-9]*/temp2_input;echo -n 'UCD: ';cat /sys/bus/i2c/devices/i2c-1/1-007e/temp1_input;cat /sys/bus/i2c/devices/1-007e/hwmon/hwmon3/temp1_input;echo -n 'FPGA: ';fpgamem 0xc0;"
    ["ecc"]="ecc_dump"
    #["power_consumption"]="fzp_get_pwr.sh -vcp"
);

declare -A fzc_commands=(
    ["systime"]="date +%s"
    ["diskspace"]="df"
);

function dumpProc
{
    declare -A inner_commands=();
    if [ $is_fzc == 1 ]; then
        sysStats=( "${fzcsysStats[@]}" )
    for key in ${!fzc_commands[@]}; do
            inner_commands["$key"]="${fzc_commands["$key"]}"
        done
    else
        for key in ${!commands[@]}; do
            inner_commands["$key"]="${commands["$key"]}"
        done
    fi
    while true; do
        if [ $verbose == 1 ]; then
            echo "Dumping /proc/..."'$\n'
        fi
        tmp=""
        for task in "${sysStats[@]}"; do
            if [ $verbose == 1 ]; then
                echo "Dumping $task...\n"
            fi
            tmp+=$'@'"$task "$'{\n'
            tmp+=$(cat /proc/$task 2>>$logsDir/err.log)
            tmp+=$'\n}@\n'
        done
        for command in "${!inner_commands[@]}"; do
            if [ $verbose == 1 ]; then
                echo "Dumping $command..."'$\n'
            fi;
            tmp+=$'@'"$command "$'{\n'
            _command=$(${inner_commands[$command]} 2>>$logsDir/err.log)
            tmp+=$_command
            tmp+=$'\n}@\n'
        done

        if [ $clear_flag == 0 ]; then
            processes=`ps ax -o pid`;
            processes_array=($processes)
            processes_array=("${processes_array[@]:1}")
            for task in ${processes_array[@]}; do
                task="$(echo "${task}" | tr -d '[:space:]')"
                if [ $verbose == 1 ]; then
                    echo "Dumping task id:"${task}" stat"
                fi;
                tmp+=$'@'"$task""/stat"$' {\n'
                _command_task=$(cat /proc/$task/stat)
                tmp+=$_command_task
                _command_pmap=$(pmap -X -p $task | tail -1 | awk '{print $3}' 2>>$logsDir/err.log)
                tmp+=" "
                tmp+=$_command_pmap
                if [[ "$_command_pmap" =~ ^\d+$ ]]; then
                    tmp+=$_command_pmap
                else
                    tmp+="0"
                fi
                tmp+=$'\n}@\n'
          done
        fi
    if [ $is_fzc == 0 ]; then
            for cpuID in "${!ccsStats[@]}"; do
                tmp+=$'@'"ccsArmCpu""$cpuID "$'{\n'
                _ccs_command=$(cat /tmp/ccs_lite/${ccsStats[$cpuID]}/fusemnt/ccsliteStats.txt 2>>$logsDir/err.log)
                tmp+=$_ccs_command
                tmp+=$'\n}@\n'
            done
        fi
    
        fileName=$logsDir"/procdump/procdump"`printf "%010d" $dumpNr`".txt"
        if [ $verbose == 1 ]; then
            echo "Opening file: "${fileName}$'\n'
        fi
        let "dumpNr++"
        let "counter++"
        touch "$fileName"
        echo "$tmp" > "$fileName"
        if [ $verbose == 1 ]; then
             echo "Dump /proc/ to "${fileName}$'\n'
        fi
        sleep $period
    done
 }

args=($@)
args_len=${#args[@]}
for ((index=0; index<=${args_len}; index++)); do
    if [[ "${args[$index]}" =~ ^-+h ]]; then
        #usage();
        echo "--h"
        exit 1      
    fi
    if [[ "${args[$index]}" =~ ^-+l && $args[$index+1] ]]; then
        logsDir=${args[$index+1]}
    fi
    if [[ "${args[$index]}" =~ ^-+c ]]; then
        clear_flag=1
    fi
    if [[ "${args[$index]}" =~ ^-+v && $args[$index+1] ]]; then
        verbose=1
    fi
    if [[ "${args[$index]}" =~ ^-+p && $args[$index+1] ]]; then
        period=${args[$index+1]}
    fi
    if [[ "${args[$index]}" =~ ^-+fzc && $args[$index+1] ]]; then
        is_fzc=1
    fi
done

if mkdir -p $logsDir 2>>/tmp/mkdir_err.log; then
    if ! rm -rf $logsDir/* 2>>$logsDir/err.log; then
        echo "Cannot clean log directory. Aborting\n"
        exit 1
    fi
    if ! mkdir -p  $logsDir"/procdump" 2>>$logsDir/err.log; then
        echo "Cannot create procdump log directory. Aborting\n"
        exit 1
    fi
    if [ $is_fzc == 2 ]; then
        IFS=$'\n'
        ccs_processes=`ps ax | grep -i ccsliteexe`
        ccs_processes_array=($ccs_processes)
        ccs_processes_array_len=${#ccs_processes_array[@]}
        for ((index=0; index<=${ccs_processes_array_len}; index++)); do
        if [[ "${ccs_processes_array[$index]}" =~ /opt/CCS/CCSLiteExe.--cpu=([0-9]*).*--nid=([0-9]x[A-Za-z0-9]*).* ]]; then
                ccsStats+=(["${BASH_REMATCH[1]}"]="${BASH_REMATCH[2]}")
            fi
        done

    fi
    dumpProc
else
    echo "Cannot create log directory. Aborting. See /tmp/mkdir_err.log file for more details"
fi;



